    addChild(m_pagemgr);
    addChild(m_setting);
    addChild(m_search);
    addChild(m_hismgr);
    addChild(m_favmgr);
    addChild(m_fillmgr);
    addChild(m_secmgr);
    addChild(m_about);
    addChild(m_menu);
    addChild(m_modebtn);
    addChild(m_backbtn);
