namespace vgcl {

class VThreadPriv;

class VThread : public VObject
{
public:
    VThread();
    virtual ~VThread();

    virtual void Run(void) = 0;

    bool Start(void);
    bool StartOnce(void);
    bool Stop(void);
    bool isRunning(void) const;
