private:
    VThread(const VThread&);
    VThread& operator=(const VThread&);

    VThreadPriv* m_data;
};

class VMutex : public VObject
{
public:
    VMutex();
    virtual ~VMutex();

    bool TryLock(void);
    bool Lock(void);
    bool UnLock(void);

private:
    VMutex(const VMutex&);
    VMutex& operator=(const VMutex&);

    PlatformMutex m_handle;
};

template<typename T>
class VMutexLocker
{
public:
    VMutexLocker(T& mutex)
        : m_mutex(mutex)
    {
        m_mutex.Lock();
    }

    ~VMutexLocker()
    {
        m_mutex.UnLock();
    }

private:
    VMutexLocker(const VMutexLocker&);
    VMutexLocker& operator=(const VMutexLocker&);

    T& m_mutex;
};

}

